65	// Register commits a new net policy. Retrying an identity with identical content
66	// returns the stored record with created=false; different content yields ErrConflict.
67	// The whole check-and-insert runs under one lock and one transaction so a failed
68	// registration leaves nothing behind and concurrent submits keep a single row.
69	func (s *Store) Register(rec Record) (stored Record, created bool, err error) {
70		rulesJSON, err := json.Marshal(rec.Rules)
71		if err != nil {
72			return Record{}, false, fmt.Errorf("encode rules: %w", err)
73		}
74		paramsJSON, err := json.Marshal(rec.PluginParams)
75		if err != nil {
76			return Record{}, false, fmt.Errorf("encode plugin params: %w", err)
77		}
78		content := contentKey(rec.Label, rulesJSON, paramsJSON)
79	
80		s.mu.Lock()
81		defer s.mu.Unlock()
82	
83		tx, err := s.db.Begin()
84		if err != nil {
85			return Record{}, false, fmt.Errorf("begin register: %w", err)
86		}
87		defer tx.Rollback()
88	
89		var (
90			existing                                       Record
91			existingRules, existingParams, existingContent string
92			existingConflict                               int
93		)
94		row := tx.QueryRow(
95			`SELECT label, rules, plugin_params, content, seq, conflict
96			 FROM net_policies WHERE namespace = ? AND name = ?`,
97			rec.Namespace, rec.Name)
98		scanErr := row.Scan(&existing.Label, &existingRules, &existingParams, &existingContent, &existing.Order, &existingConflict)
99		switch {
100		case scanErr == nil:
101			if existingContent != content {
102				return Record{}, false, ErrConflict
103			}
104			existing.Namespace, existing.Name = rec.Namespace, rec.Name
105			existing.Conflict = existingConflict != 0
106			if err := json.Unmarshal([]byte(existingRules), &existing.Rules); err != nil {
107				return Record{}, false, fmt.Errorf("decode stored rules: %w", err)
108			}
109			if err := json.Unmarshal([]byte(existingParams), &existing.PluginParams); err != nil {
110				return Record{}, false, fmt.Errorf("decode stored plugin params: %w", err)
111			}
112			return existing, false, nil
113		case !errors.Is(scanErr, sql.ErrNoRows):
114			return Record{}, false, fmt.Errorf("lookup net policy: %w", scanErr)
115		}
116	
117		conflict, err := detectConflict(tx, rec)
118		if err != nil {
119			return Record{}, false, err
120		}
121	
122		var next int64
123		if err := tx.QueryRow(`SELECT COALESCE(MAX(seq), 0) + 1 FROM net_policies`).Scan(&next); err != nil {
124			return Record{}, false, fmt.Errorf("assign order: %w", err)
125		}
126		conflictFlag := 0
127		if conflict {
128			conflictFlag = 1
129		}
130		if _, err := tx.Exec(
131			`INSERT INTO net_policies (namespace, name, label, rules, plugin_params, content, seq, conflict)
132			 VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
133			rec.Namespace, rec.Name, rec.Label, string(rulesJSON), string(paramsJSON), content, next, conflictFlag); err != nil {
134			return Record{}, false, fmt.Errorf("insert net policy: %w", err)
135		}
136		if err := tx.Commit(); err != nil {
137			return Record{}, false, fmt.Errorf("commit net policy: %w", err)
138		}
139		rec.Order = next
140		rec.Conflict = conflict
141		return rec, true, nil
142	}
