144	// List returns committed records filtered by the non-empty conditions, ordered by seq.
145	func (s *Store) List(namespace, label string) ([]Record, error) {
146		query := `SELECT namespace, name, label, rules, plugin_params, seq, conflict FROM net_policies`
147		var conds []string
148		var args []any
149		if namespace != "" {
150			conds = append(conds, "namespace = ?")
151			args = append(args, namespace)
152		}
153		if label != "" {
154			conds = append(conds, "label = ?")
155			args = append(args, label)
156		}
157		if len(conds) > 0 {
158			query += " WHERE " + strings.Join(conds, " AND ")
159		}
160		query += " ORDER BY seq ASC"
161	
162		rows, err := s.db.Query(query, args...)
