170			var (
171				rec                 Record
172				rulesRaw, paramsRaw string
173				conflictFlag        int
174			)
175			if err := rows.Scan(&rec.Namespace, &rec.Name, &rec.Label, &rulesRaw, &paramsRaw, &rec.Order, &conflictFlag); err != nil {
176				return nil, fmt.Errorf("scan net policy: %w", err)
177			}
178			if err := json.Unmarshal([]byte(rulesRaw), &rec.Rules); err != nil {
179				return nil, fmt.Errorf("decode stored rules: %w", err)
180			}
181			if err := json.Unmarshal([]byte(paramsRaw), &rec.PluginParams); err != nil {
182				return nil, fmt.Errorf("decode stored plugin params: %w", err)
183			}
184			rec.Conflict = conflictFlag != 0
185			records = append(records, rec)
186		}
187		if err := rows.Err(); err != nil {
188			return nil, fmt.Errorf("iterate net policies: %w", err)
189		}
190		return records, nil
191	}
