193	// detectConflict reports whether the candidate record clashes with any committed
194	// record sharing its namespace and label: same direction, opposite action, and
195	// overlapping port intervals.
196	func detectConflict(tx *sql.Tx, rec Record) (bool, error) {
197		rows, err := tx.Query(
198			`SELECT rules FROM net_policies WHERE namespace = ? AND label = ?`,
199			rec.Namespace, rec.Label)
200		if err != nil {
201			return false, fmt.Errorf("scan conflicts: %w", err)
202		}
203		defer rows.Close()
204	
205		for rows.Next() {
206			var raw string
207			if err := rows.Scan(&raw); err != nil {
208				return false, fmt.Errorf("scan conflict row: %w", err)
209			}
210			var existing []Rule
211			if err := json.Unmarshal([]byte(raw), &existing); err != nil {
212				return false, fmt.Errorf("decode stored rules: %w", err)
