521	// An idempotent retry containing empty/non-ASCII values returns 200 with the
522	// original record regardless of object key order, consumes no order, and the
523	// next brand-new identity keeps the expected sequence.
524	func TestPostNetPolicyIdempotentRetryWithSpecialValues(t *testing.T) {
525		router, _ := newTestRouter(t)
526		seed := policyBody("payments", "default-deny", "tier=backend", `{"zone": "华北", "mode": ""}`)
