	if err := json.Unmarshal(created.Body.Bytes(), &stored); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if stored["order"] != float64(1) {
		t.Fatalf("order = %v, want 1 (rejected request must not consume an order)", stored["order"])
	}
}

